#!/usr/bin/env python3
"""Validate and assemble the Glasshouse tabletop exercise.

Standard library only. No network access and no execution of repository content.
Run from any directory; paths are resolved from this file's parent repository.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import shutil
import sys
from datetime import datetime, timezone
from pathlib import Path, PurePosixPath
from typing import Any, Dict, Iterable, List, Sequence, Set, Tuple

ROOT = Path(__file__).resolve().parents[1]
MANIFEST = ROOT / "exercises/glasshouse/exercise.json"
LINK_RE = re.compile(r"(?<!!)\[[^\]]+\]\(([^)]+)\)")
ROUND_RE = re.compile(r"^# Inject (\d+)\b", re.MULTILINE)
TIME_RE = re.compile(r"^\*\*Release at: Round (\d+), (\d{2}):(\d{2}) fictional time\*\*", re.MULTILINE)
SYNTHETIC_LABEL = "**Classification: fictional participant material**"


class ValidationError(Exception):
    """A source validation problem, reported without a traceback to the user."""


def fail(errors: Sequence[str]) -> None:
    if errors:
        raise ValidationError("\n".join(f"- {item}" for item in errors))


def load_manifest() -> Dict[str, Any]:
    try:
        data = json.loads(MANIFEST.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise ValidationError(f"Missing manifest: {MANIFEST.relative_to(ROOT)}") from exc
    except json.JSONDecodeError as exc:
        raise ValidationError(f"Invalid JSON in manifest: {exc}") from exc
    if not isinstance(data, dict):
        raise ValidationError("Manifest must contain a JSON object")
    return data


def source_path(relative: str) -> Path:
    """Resolve a manifest path and reject traversal outside the source tree."""
    pure = PurePosixPath(relative)
    if pure.is_absolute() or not relative or any(part in ("", ".", "..") for part in pure.parts):
        raise ValidationError(f"Unsafe or invalid source path: {relative!r}")
    candidate = (ROOT / Path(*pure.parts)).resolve()
    try:
        candidate.relative_to(ROOT)
    except ValueError as exc:
        raise ValidationError(f"Source path escapes repository: {relative}") from exc
    return candidate


def check_list_of_paths(data: Dict[str, Any], key: str, errors: List[str]) -> List[str]:
    value = data.get(key)
    if not isinstance(value, list) or not value:
        errors.append(f"Manifest field {key!r} must be a non-empty list")
        return []
    paths: List[str] = []
    for item in value:
        if not isinstance(item, str):
            errors.append(f"Manifest field {key!r} contains a non-string path")
            continue
        paths.append(item)
        try:
            path = source_path(item)
        except ValidationError as exc:
            errors.append(str(exc))
            continue
        if not path.is_file():
            errors.append(f"Missing source file: {item}")
    return paths


def minutes(value: str) -> int:
    hour, minute = (int(part) for part in value.split(":"))
    if hour > 23 or minute > 59:
        raise ValueError(value)
    return hour * 60 + minute


def validate_injects(data: Dict[str, Any], start: Set[str], errors: List[str]) -> List[str]:
    raw = data.get("injects")
    if not isinstance(raw, list) or not raw:
        errors.append("Manifest field 'injects' must be a non-empty list")
        return []

    paths: List[str] = []
    rounds: List[int] = []
    times: List[str] = []
    previous_time = -1
    for index, item in enumerate(raw):
        if not isinstance(item, dict):
            errors.append(f"Inject entry {index} must be an object")
            continue
        for field in ("round", "path", "fictional_time", "distribution"):
            if field not in item:
                errors.append(f"Inject entry {index} lacks {field!r}")
        round_number = item.get("round")
        path_string = item.get("path")
        fictional_time = item.get("fictional_time")
        distribution = item.get("distribution")

        if type(round_number) is not int or round_number != index:
            errors.append(f"Inject entry {index} must have sequential round={index}")
        else:
            rounds.append(round_number)
        if distribution != ("participant_start" if index == 0 else "sealed"):
            errors.append(f"Inject round {index} has incorrect distribution")
        if not isinstance(path_string, str):
            errors.append(f"Inject entry {index} has a non-string path")
            continue
        paths.append(path_string)
        try:
            path = source_path(path_string)
        except ValidationError as exc:
            errors.append(str(exc))
            continue
        if not path.is_file():
            errors.append(f"Missing inject: {path_string}")
            continue
        text = path.read_text(encoding="utf-8")
        heading = ROUND_RE.search(text)
        timing = TIME_RE.search(text)
        if not heading or int(heading.group(1)) != index:
            errors.append(f"{path_string}: heading must declare Inject {index}")
        if not timing or int(timing.group(1)) != index:
            errors.append(f"{path_string}: release line must declare Round {index}")
        elif isinstance(fictional_time, str):
            actual_time = f"{timing.group(2)}:{timing.group(3)}"
            if fictional_time != actual_time:
                errors.append(
                    f"{path_string}: manifest time {fictional_time} != file time {actual_time}"
                )
        if SYNTHETIC_LABEL not in text:
            errors.append(f"{path_string}: missing synthetic-material label")

        if not isinstance(fictional_time, str):
            errors.append(f"Inject entry {index} has a non-string fictional_time")
        else:
            try:
                current_time = minutes(fictional_time)
            except (ValueError, TypeError):
                errors.append(f"Inject entry {index} has invalid fictional_time")
            else:
                if current_time < previous_time:
                    errors.append("Inject fictional times must be nondecreasing")
                previous_time = current_time
                times.append(fictional_time)
        if (index == 0) != (path_string in start):
            errors.append(
                f"{path_string}: inject 00 must be in participant_start; later injects must not be"
            )

    if len(set(paths)) != len(paths):
        errors.append("Inject paths must be unique")
    if rounds != list(range(5)):
        errors.append("This version requires five inject rounds numbered 0 through 4")
    if times and times[-1] != "15:46":
        errors.append("Round 4 must remain at 15:46 unless dependent guide text is also revised")
    return paths


def markdown_link_targets(text: str) -> Iterable[str]:
    for raw in LINK_RE.findall(text):
        target = raw.strip()
        if target.startswith("<") and target.endswith(">"):
            target = target[1:-1]
        # Optional titles are not used in this repository. A plain split handles
        # targets containing spaces only when they are enclosed in angle brackets.
        if not target.startswith("<"):
            target = target.split()[0] if target.split() else ""
        if not target or target.startswith(("http://", "https://", "mailto:", "#")):
            continue
        yield target.split("#", 1)[0]


def check_links(markdown_files: Iterable[Path], errors: List[str]) -> int:
    checked = 0
    for path in markdown_files:
        text = path.read_text(encoding="utf-8")
        for target in markdown_link_targets(text):
            checked += 1
            try:
                # URL-encoded paths are deliberately unsupported, making broken
                # or surprising filenames visible instead of silently ignoring them.
                if "%" in target:
                    raise ValidationError("URL-encoded links are not supported")
                destination = (path.parent / target).resolve()
                destination.relative_to(ROOT)
            except (ValueError, ValidationError):
                errors.append(f"{path.relative_to(ROOT)}: unsafe link {target!r}")
                continue
            if not destination.exists():
                errors.append(f"{path.relative_to(ROOT)}: broken link {target!r}")
    return checked


def check_timing(data: Dict[str, Any], errors: List[str]) -> None:
    guide_path = ROOT / "exercises/glasshouse/facilitator-guide.md"
    if not guide_path.is_file():
        return
    text = guide_path.read_text(encoding="utf-8")
    rows = re.findall(
        r"^\| (\d{2}):(\d{2})[–-](\d{2}):(\d{2}) \|[^|]+\|[^|]+\|[^|]+\|$",
        text,
        re.MULTILINE,
    )
    if len(rows) != 6:
        errors.append(f"Facilitator schedule must have exactly six parseable rows; found {len(rows)}")
        return
    previous_end = 0
    durations: List[int] = []
    for start_h, start_m, end_h, end_m in rows:
        start = int(start_h) * 60 + int(start_m)
        end = int(end_h) * 60 + int(end_m)
        if start != previous_end or end <= start:
            errors.append("Facilitator schedule rows must be contiguous and increasing")
        previous_end = end
        durations.append(end - start)
    if previous_end != data.get("duration_minutes"):
        errors.append("Schedule duration does not match manifest duration_minutes")
    expected = [8, 12, 15, 15, 15, 25]
    if durations != expected:
        errors.append(f"Unexpected schedule durations {durations}; expected {expected}")
    for inject in data.get("injects", []):
        if isinstance(inject, dict) and isinstance(inject.get("fictional_time"), str):
            value = inject["fictional_time"]
            if f"| {value} |" not in text:
                errors.append(f"Facilitator schedule omits fictional time {value}")


def validate() -> Tuple[Dict[str, Any], Dict[str, List[str]], Dict[str, int]]:
    errors: List[str] = []
    data = load_manifest()
    required = {
        "schema_version": 1,
        "id": "glasshouse",
        "status": "untested-draft",
        "duration_minutes": 90,
    }
    for key, expected in required.items():
        if data.get(key) != expected:
            errors.append(f"Manifest {key!r} must be {expected!r} for this builder version")

    start_list = check_list_of_paths(data, "participant_start", errors)
    facilitator_list = check_list_of_paths(data, "facilitator_only", errors)
    documentation_list = check_list_of_paths(data, "source_documentation", errors)
    start = set(start_list)
    facilitator = set(facilitator_list)
    documentation = set(documentation_list)
    overlap = start & facilitator
    if overlap:
        errors.append(f"Participant/facilitator overlap: {sorted(overlap)}")
    if documentation & (start | facilitator):
        errors.append("Source documentation must be separate from distributed participant/facilitator packs")

    inject_list = validate_injects(data, start, errors)
    injects = set(inject_list)
    if not injects.issubset(start | facilitator):
        # Sealed injects intentionally form a third distribution group. Only the
        # baseline is duplicated into the starting pack; none belongs in facilitator_only.
        unexpected = injects - start - facilitator
        if unexpected != set(inject_list[1:]):
            errors.append("Inject manifest and distribution groups disagree")

    participant_without_inject = start - injects
    if participant_without_inject != {
        "exercises/glasshouse/participant-handout.md",
        "exercises/glasshouse/safety-case.md",
        "exercises/glasshouse/decision-log.md",
    }:
        errors.append("Unexpected participant_start files; review pack separation")
    if set(facilitator_list) != {
        "exercises/glasshouse/facilitator-guide.md",
        "exercises/glasshouse/answer-key.md",
        "exercises/glasshouse/after-action-review.md",
    }:
        errors.append("Unexpected facilitator_only files; review answer-key separation")

    # Detect accidental participant access to spoilers through local links or
    # direct textual references. Filenames alone can reveal the scenario arc.
    spoiler_names = sorted(path.name for path in injects if "injects/00-" not in path)
    spoiler_names += [Path(path).name for path in facilitator_list]
    for relative in sorted(start):
        path = source_path(relative)
        text = path.read_text(encoding="utf-8")
        for target in markdown_link_targets(text):
            destination = (path.parent / target).resolve()
            try:
                target_relative = destination.relative_to(ROOT).as_posix()
            except ValueError:
                continue
            if target_relative in facilitator or (
                target_relative in injects and target_relative not in start
            ):
                errors.append(f"{relative}: participant link exposes {target_relative}")
        if relative != "exercises/glasshouse/injects/00-release-brief.md":
            for name in spoiler_names:
                if name in text:
                    errors.append(f"{relative}: participant text names spoiler file {name}")

    check_timing(data, errors)
    source_files = sorted(
        path for path in (ROOT / "exercises/glasshouse").rglob("*.md") if path.is_file()
    )
    link_count = check_links(source_files, errors)
    fail(errors)
    groups = {
        "participant_start": sorted(start),
        "sealed_injects": sorted(injects - start),
        "facilitator": sorted(facilitator),
        "documentation": sorted(documentation),
    }
    counts = {
        "source_files": len(set(start | facilitator | documentation | injects)),
        "internal_links_checked": link_count,
        "injects": len(injects),
    }
    return data, groups, counts


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def safe_output(path: Path) -> Path:
    destination = path.expanduser().resolve()
    if destination == ROOT or ROOT in destination.parents:
        # Building inside the repository is allowed only below the ignored dist/
        # directory, preventing accidental overwrites of source materials.
        try:
            destination.relative_to(ROOT / "dist")
        except ValueError as exc:
            raise ValidationError("In-repository output must be below dist/") from exc
    if destination == Path(destination.anchor):
        raise ValidationError("Refusing to use a filesystem root as output")
    return destination


def copy_group(paths: Sequence[str], destination: Path, written: Dict[Path, str]) -> None:
    for relative in paths:
        source = source_path(relative)
        target = destination / relative
        if target in written and written[target] != relative:
            raise ValidationError(f"Output collision at {target}")
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(source, target)
        written[target] = relative


def build(data: Dict[str, Any], groups: Dict[str, List[str]], output: Path) -> None:
    destination = safe_output(output)
    # Fail before deleting an existing pack if any source is unexpectedly absent.
    for paths in groups.values():
        for relative in paths:
            if not source_path(relative).is_file():
                raise ValidationError(f"Source disappeared before build: {relative}")
    if destination.exists():
        if not destination.is_dir():
            raise ValidationError("Output exists and is not a directory")
        shutil.rmtree(destination)
    destination.mkdir(parents=True)

    output_groups = {
        "participant_start": "participant-start",
        "sealed_injects": "sealed-injects",
        "facilitator": "facilitator",
        "documentation": "documentation",
    }
    written: Dict[Path, str] = {}
    for key, directory in output_groups.items():
        copy_group(groups[key], destination / directory, written)

    checksum_lines = [
        f"{sha256(path)}  {path.relative_to(destination).as_posix()}"
        for path in sorted(written)
    ]
    (destination / "checksums.sha256").write_text(
        "\n".join(checksum_lines) + "\n", encoding="utf-8"
    )
    build_record = {
        "exercise_id": data["id"],
        "exercise_version": data["version"],
        "exercise_status": data["status"],
        "built_at": datetime.now(timezone.utc).isoformat(),
        "builder": "tools/build_exercise.py",
        "groups": {
            key: {
                "directory": directory,
                "files": [path.relative_to(destination).as_posix() for path in sorted(written)
                          if written[path] in groups[key]],
            }
            for key, directory in output_groups.items()
        },
        "warning": (
            "Synthetic, untested training material. Keep sealed injects and facilitator files "
            "from participants. This build is not a safety validation."
        ),
    }
    (destination / "manifest.json").write_text(
        json.dumps(build_record, indent=2, ensure_ascii=False) + "\n", encoding="utf-8"
    )


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, help="Directory for the assembled exercise pack")
    parser.add_argument("--check-only", action="store_true", help="Validate sources without writing files")
    args = parser.parse_args()
    if args.check_only and args.output:
        parser.error("--check-only and --output are mutually exclusive")
    if not args.check_only and not args.output:
        parser.error("provide --output DIR or --check-only")
    return args


def main() -> int:
    args = parse_args()
    try:
        data, groups, counts = validate()
        if not args.check_only:
            build(data, groups, args.output)
    except ValidationError as exc:
        print(f"Validation failed:\n{exc}", file=sys.stderr)
        return 1
    except OSError as exc:
        print(f"File operation failed: {exc}", file=sys.stderr)
        return 2
    action = "Validated" if args.check_only else f"Built {args.output}"
    print(
        f"{action}: {counts['source_files']} source files, "
        f"{counts['injects']} injects, {counts['internal_links_checked']} internal links checked."
    )
    print("Status: untested draft; participant/facilitator separation checks passed.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
